result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === now` the check is `false` and the token is accepted. Per the JWT spec, a token with `exp` equal to the current time must be rejected.

**Secondary issue:** `jwt.verify()` already throws `TokenExpiredError` for expired tokens, so the manual check is largely redundant — but if kept, it needs `<=`. The catch block also swallows all errors with the same message, hiding useful context (expired vs. malformed vs. server misconfiguration).

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // jwt.verify() already rejects expired tokens, but this guard catches the
    // boundary case (exp === now) in case library clock tolerance allows it through.
    if (decoded.exp <= Date.now() / 1000) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err instanceof jwt.TokenExpiredError) {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err instanceof jwt.JsonWebTokenError) {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected error (e.g. JWT_SECRET undefined, algorithm mismatch)
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Changes summary:**
| | Before | After |
|---|---|---|
| Expiry comparison | `< Date.now() / 1000` | `<= Date.now() / 1000` |
| Expired token error | Caught generically | `TokenExpiredError` → 401 "Token expired" |
| Invalid token error | Caught generically | `JsonWebTokenError` → 401 "Invalid token" |
| Server errors | Caught generically | Falls through to 500 "Authentication error" |
